#!/usr/bin/env python3
"""Compute ground truth for CSX-006_Q1."""

from __future__ import annotations

import csv
import json
from datetime import date
from pathlib import Path
from typing import Any


TASK_ID = "CSX-006_Q1"
EVENT_ID = "CSX-006"

EVENT_ANCHOR = (
    "data/event_reports/"
    "event_reports_003_Locked_event_anchor_March-April_2024_West_Africa_and_Sahel_humid_heat_wave.json"
)
OPEN_METEO = "data/physical_hazard/physical_hazard_001_Open-Meteo_historical_archive.json"
WWA_REPORT = "data/event_reports/event_reports_004_World_Weather_Attribution_-_Sahel_humid_heat_wave.html"
ERA5_AGGREGATE = "data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json"

SOURCE_PATHS = [
    "metadata/event.json",
    "metadata/files.csv",
    EVENT_ANCHOR,
    OPEN_METEO,
    WWA_REPORT,
    ERA5_AGGREGATE,
]


def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def package_dir() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID


def read_json(package: Path, rel_path: str) -> Any:
    return json.loads((package / rel_path).read_text(encoding="utf-8-sig"))


def read_text(package: Path, rel_path: str) -> str:
    return (package / rel_path).read_text(encoding="utf-8-sig", errors="replace")


def inclusive_days(start: str, end: str) -> int:
    start_date = date.fromisoformat(start)
    end_date = date.fromisoformat(end)
    return (end_date - start_date).days + 1


def in_window(day: str, start: str, end: str) -> bool:
    return start <= day <= end


def round_mean(values: list[float], digits: int = 2) -> float:
    if not values:
        raise ValueError("Cannot compute mean of an empty list")
    return round(sum(values) / len(values), digits)


def hottest_window(values: list[float], dates: list[str], window_days: int) -> dict[str, object]:
    if len(values) < window_days:
        raise ValueError("Not enough values for rolling-window computation")

    best_start = 0
    best_mean = float("-inf")
    for start in range(len(values) - window_days + 1):
        mean_value = sum(values[start : start + window_days]) / window_days
        if mean_value > best_mean:
            best_start = start
            best_mean = mean_value

    return {
        "start_date": dates[best_start],
        "end_date": dates[best_start + window_days - 1],
        "mean_apparent_tmax_c": round(best_mean, 1),
    }


def manifest_paths(package: Path) -> set[str]:
    with (package / "metadata/files.csv").open(newline="", encoding="utf-8-sig") as f:
        return {row["relative_path"] for row in csv.DictReader(f)}


def main() -> None:
    package = package_dir()

    event = read_json(package, "metadata/event.json")
    if event["package_id"] != EVENT_ID:
        raise ValueError("Unexpected package_id in metadata/event.json")

    paths = manifest_paths(package)
    for rel_path in SOURCE_PATHS[2:]:
        if rel_path not in paths:
            raise ValueError(f"Source file is not listed in metadata/files.csv: {rel_path}")

    anchor = read_json(package, EVENT_ANCHOR)
    weather = read_json(package, OPEN_METEO)
    era5 = read_json(package, ERA5_AGGREGATE)
    report_html = read_text(package, WWA_REPORT)

    start_date = anchor["temporal_window"]["start_date"]
    end_date = anchor["temporal_window"]["end_date"]
    event_days = inclusive_days(start_date, end_date)

    daily = weather["daily"]
    daily_rows = [
        {
            "date": day,
            "air_tmax": float(daily["temperature_2m_max"][idx]),
            "air_tmin": float(daily["temperature_2m_min"][idx]),
            "apparent_tmax": float(daily["apparent_temperature_max"][idx]),
        }
        for idx, day in enumerate(daily["time"])
        if in_window(day, start_date, end_date)
    ]

    if len(daily_rows) != event_days:
        raise ValueError(f"Expected {event_days} daily rows in event window, found {len(daily_rows)}")

    dates = [row["date"] for row in daily_rows]
    apparent_tmax = [row["apparent_tmax"] for row in daily_rows]
    air_tmax = [row["air_tmax"] for row in daily_rows]
    air_tmin = [row["air_tmin"] for row in daily_rows]
    daily_app_minus_air = [app - air for app, air in zip(apparent_tmax, air_tmax)]

    heat_load = round(sum(max(value - 39.0, 0.0) for value in apparent_tmax), 1)
    warm_nights = sum(value >= 27.0 for value in air_tmin)
    warm_night_ratio = round(warm_nights / event_days, 2)
    hottest_3day = hottest_window(apparent_tmax, dates, 3)

    hourly = weather["hourly"]
    hot_rows = []
    for idx, timestamp in enumerate(hourly["time"]):
        day = timestamp[:10]
        if not in_window(day, start_date, end_date):
            continue
        air = float(hourly["temperature_2m"][idx])
        if air < 39.0:
            continue
        apparent = float(hourly["apparent_temperature"][idx])
        rh = float(hourly["relative_humidity_2m"][idx])
        dew_point = float(hourly["dew_point_2m"][idx])
        hot_rows.append(
            {
                "time": timestamp,
                "temperature_2m_c": air,
                "apparent_temperature_c": apparent,
                "relative_humidity_pct": rh,
                "dew_point_c": dew_point,
                "apparent_minus_air_c": apparent - air,
            }
        )

    if not hot_rows:
        raise ValueError("No hourly rows meet the hot-hour rule")

    mean_hot_hour_app_minus_air = round_mean(
        [row["apparent_minus_air_c"] for row in hot_rows],
        2,
    )
    mean_hot_hour_rh = round_mean([row["relative_humidity_pct"] for row in hot_rows], 2)
    mean_hot_hour_dew_point = round_mean([row["dew_point_c"] for row in hot_rows], 2)
    hot_hours_rh_ge30 = sum(row["relative_humidity_pct"] >= 30.0 for row in hot_rows)
    hot_hours_apparent_gt_air = sum(row["apparent_minus_air_c"] > 0.0 for row in hot_rows)

    daily_mean_app_minus_air = round_mean(daily_app_minus_air, 2)
    days_apparent_tmax_gt_air_tmax = sum(delta > 0.0 for delta in daily_app_minus_air)

    # ERA5 aggregate stats are read to prove the tempting substitute lacks the fields
    # required for the humid-heat mechanism audit.
    era5_stat_keys = set(era5["stats"].keys())
    era5_missing_fields = [
        "relative_humidity_2m",
        "dew_point_2m",
        "apparent_temperature",
    ]
    if any(field in era5_stat_keys for field in era5_missing_fields):
        raise ValueError("ERA5 aggregate unexpectedly contains a humid-heat audit field")

    anchor_has_humid_label = "humid heat wave" in anchor["event_name"].lower()
    report_has_heat_context = "sahel heatwave" in report_html.lower() or "extreme heat" in report_html.lower()
    if not anchor_has_humid_label:
        raise ValueError("Expected locked anchor to contain the humid heat-wave event label")
    if not report_has_heat_context:
        raise ValueError("Expected report HTML to contain regional heatwave context")

    not_humid_dominated = (
        mean_hot_hour_rh < 30.0
        and hot_hours_rh_ge30 == 0
        and mean_hot_hour_app_minus_air <= 0.0
        and daily_mean_app_minus_air <= 0.0
    )

    final_answer = {
        "answer_type": "humid_dry_mechanism_audit",
        "mechanism_ruling": (
            "point_evidence_dry_hot_not_humid_dominated"
            if not_humid_dominated
            else "point_evidence_humid_dominated"
        ),
        "source_paths": {
            "event_window": EVENT_ANCHOR,
            "direct_hourly_and_daily_product": OPEN_METEO,
            "report_context": WWA_REPORT,
            "insufficient_aggregate_product": ERA5_AGGREGATE,
        },
        "event_window": {
            "start_date": start_date,
            "end_date": end_date,
            "days": event_days,
        },
        "calculations": {
            "daily_apparent_heat": {
                "apparent_tmax_c": {
                    row["date"]: round(row["apparent_tmax"], 1) for row in daily_rows
                },
                "days_apparent_tmax_ge39c": sum(value >= 39.0 for value in apparent_tmax),
                "heat_load_gt39c_c_days": heat_load,
                "hottest_3day_window": hottest_3day,
            },
            "warm_nights": {
                "tmin_c": {row["date"]: round(row["air_tmin"], 1) for row in daily_rows},
                "warm_nights_tmin_ge27c": warm_nights,
                "warm_night_ratio": warm_night_ratio,
            },
            "hot_hour_moisture_gate": {
                "hot_hour_rule": "temperature_2m >= 39 C",
                "hot_hour_count": len(hot_rows),
                "mean_relative_humidity_pct": mean_hot_hour_rh,
                "mean_dew_point_c": mean_hot_hour_dew_point,
                "hot_hours_rh_ge30pct_count": hot_hours_rh_ge30,
            },
            "apparent_amplification_gate": {
                "mean_hot_hour_apparent_minus_air_c": mean_hot_hour_app_minus_air,
                "hot_hours_apparent_gt_air_count": hot_hours_apparent_gt_air,
                "daily_mean_apparent_minus_air_c": daily_mean_app_minus_air,
                "days_apparent_tmax_gt_air_tmax": days_apparent_tmax_gt_air_tmax,
            },
        },
        "rejected_or_insufficient_alternatives": {
            "anchor_or_report_label_only_humid_dominance": (
                "insufficient_for_point_mechanism_without_hourly_moisture_support"
            ),
            "era5_land_aggregate_for_humid_heat": (
                "insufficient_missing_relative_humidity_dew_point_and_apparent_temperature_fields"
            ),
            "single_dry_bulb_spike_only": (
                "rejected_because_apparent_heat_load_is_14.1_c_days_and_all_5_nights_have_tmin_ge27c"
            ),
        },
        "reference_solving_trace": [
            "Read the locked event anchor to get the 2024-03-31 to 2024-04-04 window.",
            "Use Open-Meteo because it contains both daily apparent Tmax/Tmin and hourly temperature, RH, dew point, and apparent temperature.",
            "Compute the sustained daily apparent-heat and warm-night checks from the daily arrays.",
            "Filter hourly rows to temperature_2m >= 39 C and compute moisture and apparent-minus-air indicators.",
            "Reject anchor/report-label-only humid dominance and ERA5 aggregate substitution because they cannot reproduce the point-scale moisture gate.",
        ],
    }
    compact_primary_gt = {
        "answer": final_answer["mechanism_ruling"],
        "answer_type": "humid_dry_mechanism_audit",
        "mechanism_ruling": final_answer["mechanism_ruling"],
        "selected_direct_product": OPEN_METEO,
        "key_values": {
            "heat_load_gt39c_c_days": heat_load,
            "warm_night_ratio": warm_night_ratio,
            "hot_hour_count": len(hot_rows),
            "mean_relative_humidity_pct": mean_hot_hour_rh,
            "mean_dew_point_c": mean_hot_hour_dew_point,
            "mean_hot_hour_apparent_minus_air_c": mean_hot_hour_app_minus_air,
        },
        "rejected_alternatives": [
            "anchor_or_report_label_only_humid_dominance",
            "era5_land_aggregate_for_humid_heat",
            "single_dry_bulb_spike_only",
        ],
    }

    result = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "evaluation_mode": "hybrid",
        "target_family": "humid_dry_mechanism_audit",
        "difficulty_level": "L4",
        "primary_gt": compact_primary_gt,
        "answer_detail": {
            "expected_answer": final_answer,
        },
        "event": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date_or_window": f"{start_date} to {end_date}",
            "region_focus": "West Africa and Sahel, especially Mali and Burkina Faso",
        },
        "decision_rule": {
            "required_answer_form": (
                "Compact JSON with exactly the top-level keys requested in question_en.md."
            ),
            "mechanism_classification_rule": (
                "Classify as point_evidence_dry_hot_not_humid_dominated when hot-hour "
                "mean RH is below 30%, no hot hours have RH >= 30%, and apparent "
                "temperature is not amplified above air temperature on average."
            ),
            "hot_hour_rule": "temperature_2m >= 39 C",
            "numeric_tolerances": {
                "heat_load_gt39c_c_days": 0.2,
                "hottest_3day_mean_apparent_tmax_c": 0.2,
                "warm_night_ratio": 0.01,
                "mean_relative_humidity_pct": 0.05,
                "mean_dew_point_c": 0.05,
                "mean_hot_hour_apparent_minus_air_c": 0.05,
                "daily_mean_apparent_minus_air_c": 0.05,
            },
        },
        "source_audit": {
            "selected_direct_product": OPEN_METEO,
            "selected_direct_product_reason": (
                "Only inspected numeric product with daily apparent Tmax/Tmin plus hourly "
                "temperature, relative humidity, dew point, and apparent temperature."
            ),
            "context_report": WWA_REPORT,
            "context_report_role": "regional heatwave narrative and impact context, not sufficient alone",
            "insufficient_product": ERA5_AGGREGATE,
            "insufficient_product_missing_fields": era5_missing_fields,
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "Schema and paths",
                    "points": 2,
                    "description": (
                        "Returns the required JSON schema with the exact seven top-level keys "
                        "and package-relative paths."
                    ),
                    "partial_credit": "Award 1 point for mostly correct JSON with minor key naming or path-role omissions.",
                },
                {
                    "name": "Source selection",
                    "points": 2,
                    "description": (
                        "Selects Open-Meteo as the direct numeric source and identifies the "
                        "locked anchor as the event-window source."
                    ),
                    "partial_credit": "Award 1 point if the answer uses Open-Meteo values but does not clearly explain the source role boundary.",
                },
                {
                    "name": "Sustained apparent heat",
                    "points": 3,
                    "description": (
                        "Computes 14.1 C-days, 5 days >= 39 C, and the 2024-04-02 to "
                        "2024-04-04 rolling mean of 42.5 C."
                    ),
                    "partial_credit": "Award 1-2 points for correct method with one minor arithmetic or rounding error.",
                },
                {
                    "name": "Warm-night persistence",
                    "points": 2,
                    "description": "Computes warm-night persistence as 5/5 = 1.0.",
                    "partial_credit": "Award 1 point if all warm nights are recognized but the ratio or threshold is missing.",
                },
                {
                    "name": "Hot-hour moisture gate",
                    "points": 4,
                    "description": (
                        "Filters hot hours correctly and reports 39 hot hours, 10.36% mean RH, "
                        "3.58 C mean dew point, and 0 hot hours with RH >= 30%."
                    ),
                    "partial_credit": "Award 2-3 points for correct filtering with minor mean-value differences; award 1 point for using hourly humidity but the wrong hot-hour rule.",
                },
                {
                    "name": "Apparent-amplification gate",
                    "points": 3,
                    "description": (
                        "Reports -2.24 C mean hot-hour apparent-minus-air, 7 hot hours with "
                        "apparent > air, -1.2 C daily mean apparent-minus-air, and 1 day with "
                        "apparent Tmax > air Tmax."
                    ),
                    "partial_credit": "Award 1-2 points for computing either hourly or daily apparent-minus-air correctly but not both.",
                },
                {
                    "name": "Mechanism ruling",
                    "points": 2,
                    "description": (
                        "Classifies the point evidence as dry-hot/not humid-dominated while "
                        "preserving the sustained apparent heat and warm-night findings."
                    ),
                    "partial_credit": "Award 1 point if the answer gives the correct dry-hot limitation but loses either sustained heat or warm-night context.",
                },
                {
                    "name": "Rejected alternatives",
                    "points": 2,
                    "description": (
                        "Rejects anchor/report-label-only humid dominance and ERA5 aggregate "
                        "substitution with specific evidence reasons."
                    ),
                    "partial_credit": "Award 1 point if only one rejected alternative is explained correctly.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_PATHS,
        },
    }

    out_path = Path(__file__).resolve().parent / "computed_gt.json"
    out_path.write_text(json.dumps(result, indent=2, sort_keys=False) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
